Q: Dynamics CRM SDK - IN operator for linq with OrganizationServiceContext A: <p>As per others, I've also implemented a query expression builder, but mine also allows you to specify a batch size so you don't hit any parameter query limit if you have a large list.</p>
<pre><code> public class DataverseRecordQueryService
    {
        public List&lt;T&gt; GetRecordsByIds&lt;T&gt;(OrganizationServiceContext context, IEnumerable&lt;Guid&gt; IDs, Expression&lt;Func&lt;T, bool&gt;&gt; predicate = null, int batchSize = 49)
            where T : Entity
        {
            var retVal = new List&lt;T&gt;();
            for (int i = 0; i &lt; IDs.Count(); i += batchSize)
            {
                var batch = IDs.Skip(i).Take(batchSize).ToList();
                var batchExpression = BuildOrExpression&lt;T, Guid&gt;(&quot;Id&quot;, batch);

                var batchCourseSetQuery = context.CreateQuery&lt;T&gt;().Where(batchExpression);
                if (predicate != null)
                {
                    batchCourseSetQuery = batchCourseSetQuery.Where(predicate);
                }

                retVal.AddRange(batchCourseSetQuery.ToList());
            }
            return retVal;
        }

        public List&lt;T&gt; GetRecordsByPropertyNameAndIds&lt;T, TPropertyType&gt;(OrganizationServiceContext context, string propertyName, IEnumerable&lt;TPropertyType&gt; IDs, Expression&lt;Func&lt;T, bool&gt;&gt; predicate = null, int batchSize = 49)
            where T : Entity
        {
            var retVal = new List&lt;T&gt;();

            // Get the EntityLogicalNameAttribute applied to the class
            EntityLogicalNameAttribute attribute = (EntityLogicalNameAttribute)Attribute.GetCustomAttribute(typeof(T), typeof(EntityLogicalNameAttribute));
            if (attribute != null)
            {
                for (int i = 0; i &lt; IDs.Count(); i += batchSize)
                {
                    var batch = IDs.Skip(i).Take(batchSize).ToList();
                    var batchExpression = BuildOrExpression&lt;T, TPropertyType&gt;(propertyName, batch);
                    var batchCourseSetQuery = context.CreateQuery&lt;T&gt;().Where(batchExpression);
                    if (predicate != null)
                    {
                        batchCourseSetQuery = batchCourseSetQuery.Where(predicate);
                    }
                    retVal.AddRange(batchCourseSetQuery.ToList());
                }
            }
            return retVal;
        }

        private Expression&lt;Func&lt;T, bool&gt;&gt; BuildOrExpression&lt;T, TPropertyType&gt;(string propertyName, IEnumerable&lt;TPropertyType&gt; values)
        {
            var parameter = Expression.Parameter(typeof(T), &quot;x&quot;);
            var property = Expression.Property(parameter, propertyName);

            var orExpressions = values.Select(value =&gt;
                Expression.Equal(property, Expression.Constant(value, typeof(TPropertyType)))
            );
            var body = orExpressions.Aggregate(Expression.Or);
            return Expression.Lambda&lt;Func&lt;T, bool&gt;&gt;(body, parameter);
        }
    }
</code></pre>
<p>Available on my github with detailed comments <a href="https://github.com/RealPlasticCheese/DataverseHelpers" rel="nofollow noreferrer">https://github.com/RealPlasticCheese/DataverseHelpers</a></p>

Q: Change the value of a bool method A: <p>It depends on the context in which you want to use that method. If it's a method that you use to tell a view controller if it can display or not the navigation bar, one option is create a superclass, from which view controller C inherits, and define that method there. Then, override that method in your view controller C which should inherit from the superclass. Like this:</p>

<pre><code>@interface MySuperclass : UIViewController
- (BOOL)prefersNavigationBarHidden;
@end

@implementation MySuperclass
-(BOOL)prefersNavigationBarHidden {
    return YES;
}

/*
  Use the value returned by the method to achieve what you want
  with that boolean value
*/
@end

//--------------------

@interface ViewControllerC : MySuperclass
@end

@implementation ViewControllerC
- (BOOL)prefersNavigationBarHidden {
    return NO; // return no for example
}
@end
</code></pre>

<p>It may not be your case, but it's for you to get an idea. As I told you, it depends on what you are trying to achieve.</p>
